int git_pkt_parse(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref, *msg;
    size_t ref_len, msg_len;
    const char *pos;

    if (!line || len == 0 || len > SIZE_MAX - 1) {
        return -1;
    }

    pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    // Find the end of the reference part
    pos = memchr(line, '\0', len);
    if (!pos || pos == line) {
        free(pkt);
        return -1;
    }

    ref_len = (size_t)(pos - line);
    ref = (char *)malloc(ref_len + 1);
    if (!ref) {
        free(pkt);
        return -1;
    }

    memcpy(ref, line, ref_len);
    ref[ref_len] = '\0';

    // Set the message part (everything after the first NUL character)
    pos++;  // Skip the NUL character
    msg_len = len - (pos - line);
    msg = (char *)malloc(msg_len + 1);
    if (!msg) {
        free(ref);
        free(pkt);
        return -1;
    }

    if (msg_len > 0) {
        memcpy(msg, pos, msg_len);
    }
    msg[msg_len] = '\0';

    pkt->type = GIT_PKT_TYPE_REF;
    pkt->ref = ref;
    pkt->msg = msg;

    *out = (git_pkt *)pkt;
    return 0;
}

int git_pkt_parse_network_packet(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt = NULL;
    const char *end;

    // Check for valid input
    if (!line || len < 5) {
        return -1;
    }

    // Allocate memory for the new packet
    pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    // Parse the packet length (first 4 bytes)
    pkt->len = 0;
    for (size_t i = 0; i < 4 && i < len; ++i) {
        if (!isdigit(line[i])) {
            free(pkt);
            return -1;
        }
        pkt->len = pkt->len * 10 + (line[i] - '0');
    }

    // Ensure the length is valid and within the input bounds
    if (pkt->len > len - 4) {
        free(pkt);
        return -1;
    }

    // Set the data and message pointers
    pkt->data = (char *)malloc(pkt->len + 1);
    if (!pkt->data) {
        free(pkt);
        return -1;
    }

    memcpy(pkt->data, line + 4, pkt->len);
    ((char *)pkt->data)[pkt->len] = '\0'; // Null-terminate the string

    pkt->message = NULL;

    // Set the parsed packet in the output
    *out = (git_pkt *)pkt;
    return 0;
}

